// Worker entry point.
//
// Wraps the handler generated by `opennextjs-cloudflare build` with Sentry
// (@sentry/nextjs's Node.js server instrumentation does not run on Workers)
// and re-exports the Durable Objects OpenNext relies on.
import { withSentry } from '@sentry/nextjs/cloudflare';
// @ts-ignore: generated by `opennextjs-cloudflare build`
import handler from './.open-next/worker.js';

// @ts-ignore: generated by `opennextjs-cloudflare build`
export { DOQueueHandler } from './.open-next/worker.js';

export default withSentry(
  (env: CloudflareEnv) => ({
    dsn: env.SENTRY_DSN,
    tracesSampleRate: 1.0,
  }),
  handler
);
